WITH base AS (SELECT * FROM employees WHERE LOWER(full_name) LIKE '%lic%'), summary AS (SELECT level, CASE WHEN job_title IN ('Analyst', 'Designer') THEN 'priority' ELSE 'other' END job_title_group, SUM(salary) total_salary FROM base GROUP BY level, CASE WHEN job_title IN ('Analyst', 'Designer') THEN 'priority' ELSE 'other' END) SELECT level, job_title_group, total_salary FROM summary ORDER BY job_title_group, level LIMIT 20
